/**
 * UptimeRobot Node - Version 1
 * Discriminator: resource=monitor, operation=get
 */


interface Credentials {
  uptimeRobotApi: CredentialReference;
}

/** Get account details */
export type UptimeRobotV1MonitorGetParams = {
  resource: 'monitor';
  operation: 'get';
/**
 * The ID of the monitor
 */
    id: string | Expression<string>;
};

export type UptimeRobotV1MonitorGetOutput = {
  create_datetime?: number;
  friendly_name?: string;
  http_password?: string;
  http_username?: string;
  id?: number;
  interval?: number;
  keyword_value?: string;
  port?: string;
  status?: number;
  sub_type?: string;
  timeout?: number;
  type?: number;
  url?: string;
};

export type UptimeRobotV1MonitorGetNode = {
  type: 'n8n-nodes-base.uptimeRobot';
  version: 1;
  config: NodeConfig<UptimeRobotV1MonitorGetParams> & { credentials?: Credentials };
  output?: Items<UptimeRobotV1MonitorGetOutput>;
};